// Generado (Pasada S.1): fuentes woff embebidas en base64. Se EMBEBEN para no
// depender de una descarga en runtime — el fetch al mismo origen devolvía el HTML
// del SSO de Vercel en previews protegidos (Deployment Protection) en vez del woff,
// y satori lanzaba 500. Embebido: funciona igual en local, preview y prod.
const b64 = (s: string): Buffer => Buffer.from(s, "base64");
export const SYNE_800 = b64("");
export const OUTFIT_400 = b64("");
export const OUTFIT_700 = b64("");


